import{_ as t,l as s,o as a,c as l,v as o,p as d,x as r,d as c,i as n,S as E}from"./chunks/framework.InCnrqk-.js";const V=JSON.parse('{"title":"Verilog / SystemVerilog 基本","description":"","frontmatter":{"title":"Verilog / SystemVerilog 基本","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/verilog-basics.md","filePath":"cs/verilog-basics.md","lastUpdated":1789023840000}'),p={name:"cs/verilog-basics.md"};function h(g,e,m,A,u,_){const i=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="verilog-systemverilog-基本" tabindex="-1">Verilog / SystemVerilog 基本 <a class="header-anchor" href="#verilog-systemverilog-基本" aria-label="Permalink to &quot;Verilog / SystemVerilog 基本&quot;">​</a></h1><div class="epigraph"><p>HDL 描述的是硬件结构与并行行为，不是按行执行的软件；模块、端口与 always 块最终要落到门与触发器上。</p><footer>—— 据 IEEE Std 1364（Verilog）；IEEE Std 1800（SystemVerilog）；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/saturating-arith">上一课</a>把算术单元收到饱和 MUX。那些框图还不能交给综合器。缺口是<strong>硬件描述语言</strong>：用模块把 <a href="/cs/adder-cla">CLA</a>、乘法树、饱和夹紧写成可综合的文本。本单元从代码走到芯片，不重开类型论，不写 Transformer 层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组成课用原理图画 ALU。缺口是：如何让工具生成网表。Verilog 的 <code>module</code>/<code>input</code>/<code>output</code>/<code>wire</code>/<code>reg</code>（SV 的 <code>logic</code>）对应端口与节点。组合用 <code>assign</code> 或 <code>always @(*)</code>；时序用 <code>always @(posedge clk)</code>。SystemVerilog 在此之上加接口、断言、类型，本课只钉能综合出算术单元的子集。</p><p>仿真语义与综合语义并不自动一致——下一课阻塞/非阻塞才把这个缺口钉死。本课先建立词汇。</p><h3 id="hdl-不是「在-fpga-里跑-c」" tabindex="-1">HDL 不是「在 FPGA 里跑 C」 <a class="header-anchor" href="#hdl-不是「在-fpga-里跑-c」" aria-label="Permalink to &quot;HDL 不是「在 FPGA 里跑 C」&quot;">​</a></h3><p><code>for</code> 展开的是硬件复制或生成循环，不是运行时迭代（除非综合器认成状态机，本课不依赖那条）。把 Verilog 当脚本语言写乘法，会综合出意外锁存或巨大组合环。算法用 C 是后课 HLS 的入口，本课保持 RTL 思维。</p><p><span class="marginnote">Harris 用 SystemVerilog 教 RTL。IEEE 1364/1800 是语言标准。本课不背全部语法，只够写出上一单元的加法器与饱和块。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>层次：顶层例化 ALU、乘除单元、FPU。端口列出时钟、复位、操作数与旗标。组合：<code>assign sum = a + b;</code> 依赖综合器推断加法器——面积/延迟用约束，不在源码里画华莱士，除非手写 CSA。时序：把组合结果在边沿打入寄存器，对应流水线级。</p>',11)),(a(),d(E,null,{default:r(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RTL%5B%22%E6%A8%A1%E5%9D%97%E4%B8%8E%E7%AB%AF%E5%8F%A3%22%5D%20--%3E%20COMB%5B%22%E7%BB%84%E5%90%88%20assign%20%2F%20always%22%5D%0A%20%20RTL%20--%3E%20SEQ%5B%22posedge%20%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20COMB%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%98%BB%E5%A1%9E%E4%B8%8E%E9%9D%9E%E9%98%BB%E5%A1%9E%22%5D%0A%20%20SEQ%20--%3E%20LATER%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p><code>generate</code> 复制位片，对应阵列乘法的规则结构。测试平台是后课验证，本课承认 <code>initial</code> 不可综合。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课综合把 RTL 映射到标准单元或 FPGA LUT。本课写下的 <code>+</code> 可能变成 CLA 或行波，由工具与约束决定——与<a href="/cs/adder-cla">加法器课</a>的手工结构对照：HDL 把结构选择部分交给综合。复位、时钟使能在后几课才策略化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 UVM 类库，不把 Python 生成 Verilog 当主体。不引入模拟晶体管级。也不把「AI 写 HDL」当成流程。</p><p>后课默认：可综合子集是模块、组合与边沿寄存器；下一课赋值语义决定仿真是否等于硬件。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>算术单元要用 RTL 交给工具，不是只停留在框图。</li><li>Verilog/SV 描述并行硬件；<code>for</code> 默认是展开。</li><li>仿真与综合的裂缝下一课用赋值类型去补。</li><li>出处：IEEE 1364；IEEE 1800；Harris and Harris。</li></ul>',8))])}const S=t(p,[["render",h]]);export{V as __pageData,S as default};
